import{S as a,o as s,c as n,a9 as i,B as l}from"./chunks/framework.DxG24V0C.js";const p="/agentsrc/images/opencode/07-plan-execute-verify-roles.svg",d="/agentsrc/images/opencode/07-execution-state-machine.svg",r="/agentsrc/images/opencode/07-verification-gates.svg",g=JSON.parse('{"title":"OpenCode 编排模式：plan-execute-verify 的角色拆分、硬边界与验证关卡","description":"","frontmatter":{"title":"OpenCode 编排模式：plan-execute-verify 的角色拆分、硬边界与验证关卡"},"headers":[],"relativePath":"opencode/07-plan-execute-verify.md","filePath":"opencode/07-plan-execute-verify.md","lastUpdated":1788319991000}'),u={name:"opencode/07-plan-execute-verify.md"},k=Object.assign(u,{setup(c){const e=[{question:"范围蔓延的本质是「决策权与执行权未做分离」。plan-execute-verify 编排机制是如何在 Plan（规划）阶段堵住这一风险的？",options:["让规划师直接进行代码实现，以最快速度明确任务边界","给规划师仅配置只读工具，并设置 Hook 硬性拒绝非 .omo 文件的写入","将执行调度权集中在规划师一人手中，以避免范围不定","换用更强的模型让规划师一次性思考到位，从而消除范围蔓延"],correct:1,explanation:"Plan 阶段把决策权（规划师）用只读硬边界隔离——allowed-tools 白名单只放行 .omo/*.md，prometheus-md-only 钩子在 tool.execute.before 上拒绝其余写入。这样规划师无法越界实现，范围蔓延在源头被堵。"},{question:"Execute 阶段为什么要用 boulder.json 持久化编排状态，而不是只依赖 LLM 的上下文？",options:["为了把「现在做什么/做了几件」从易失上下文抽到可查询、可恢复的磁盘状态","为了让模型在处理上下文时有一个更大的 token 缓存减少调用费","为了让用户能随时修改计划文件而不断言流水线一致性","为了把执行调度完全静态化使规划阶段不再需要任何决策"],correct:0,explanation:"boulder.json 记录 plan_name/status/session_ids/进度，把执行状态从 LLM 上下文里抽出。在线程崩溃、关机、token 超限等中断场景下，系统能按磁盘状态续跑而不是重讲一遍——这是「可恢复」这一设计点的落点。"},{question:"COMPLETION GATE 要求执行者 Edit 计划文件把 checkbox 从 - [ ] 改为 - [x]，再 Read 一次确认。这项要求的本质作用是什么？",options:["让执行者每次完成任务都留下一个可核对的进度锚点而非口头声明","让执行者通过反复编辑文件来增加上下文中的信息密度","让执行者以编辑计划为手段来扩大自己对范围的定义权","让执行者在完成后立即关闭会话以节省 token 消耗"],correct:0,explanation:"它把「完成」的唯一证据定义为磁盘文件里 checkbox 的变更，强制执行者在宣称完成前先更新计划文件再读回确认。这样进度锚在计划文件（唯一事实源），执行者不能以「我改完代码了」这类叙述替代可核对的进度变化，堵住验证缺口的最浅形态。"},{question:"VERIFICATION_REMINDER 开头断言「THE SUBAGENT IS PROBABLY LYING」。这种对抗性信念和「信任但验证」的差别在哪？",options:["对抗模式把举证责任交给验证者去证明好，而非执行者自证","对抗模式意味着验证者完全不运行任何确定性工具只看叙述","对抗模式只适用于执行者是子代理而规划师绝对可信的场景","对抗模式用更强模型重复执行同一次自证以提高可信度"],correct:0,explanation:"信任但验证把举证责任交给执行者（自证做对）；对抗模式假设坏、要求验证者用 git diff/Read/lsp_diagnostics/跑测试等确定性工具主动证明好，并把证据链抓在手里。幻觉是 base rate，验证者手里的可复现证据链才稳。"},{question:"Final Verification Wave 在整套编排里扮演什么角色，为何它是唯一需要用户审批的时刻？",options:["它是执行前的计划确认要用户先点头再审阅文档","它把收尾统验与唯一用户审批点集中在最后避免频繁打断","它是执行态每轮任务的常规进度汇报途径","它允许验证者在任何关卡直接跳过用户直接放行"],correct:1,explanation:"所有实现 todo 勾完后才进入 Final Wave 统验批次，且它由 shouldPauseForApproval 决定走审批路径，是唯一要求用户显式点头后再标记终审项的时刻。规划、执行、自动验证全程不打扰人，只在结尾把终审结论交用户裁决——既不让机器脱离人判断，也不让人反复被打断。"}];return(h,t)=>{const o=a("Quiz");return s(),n("div",null,[t[0]||(t[0]=i('<h1 id="opencode-编排模式-plan-execute-verify-的角色拆分、硬边界与验证关卡" tabindex="-1">OpenCode 编排模式：plan-execute-verify 的角色拆分、硬边界与验证关卡 <a class="header-anchor" href="#opencode-编排模式-plan-execute-verify-的角色拆分、硬边界与验证关卡" aria-label="Permalink to &quot;OpenCode 编排模式：plan-execute-verify 的角色拆分、硬边界与验证关卡&quot;">​</a></h1><p>一个单循环 agent 在真实工程里常会撞出这样一幕：它一边读代码定位问题、一边动手改、一边又回头查文档，读和写的角色混在同一条上下文里，改着改着就偏离了最初目标；最后它在答复里写下&quot;完成了、测过了&quot;，却没有任何机制能证明这句话。这是很多 agent 系统都逃不掉的毛病。</p><p>让 agent 又动手又验证、还要防着它跑偏，光靠一条 runLoop 单循环够吗？本系列前面把内核的 runLoop、工具、Agent、上下文都拆过了，这一篇换一个载体回答这个问题：一个构建在 OpenCode 之上的开源插件 <code>oh-my-openagent</code>（4.9.2），把&quot;一个单体 agent&quot;重构成&quot;一支分工明确、有状态、有验证关卡的小团队&quot;。它没给内核加魔法，只是<strong>用原生的积木搭出 plan / execute / verify 三种有界角色</strong>，每个角色配一道硬约束锁住它能碰的操作范围。</p><p>本文将深入拆解这套编排机制的运转逻辑：</p><ul><li><strong>第一</strong>，为什么要把一条循环拆成三个角色、各自隔离权力边界；</li><li><strong>第二</strong>，plan / execute / verify 各拿哪一道硬约束，守住&quot;该做的&quot;和&quot;不该碰的&quot;；</li><li><strong>第三</strong>，这套编排最终给原生内核带来什么启示。</li></ul><p>载体是你自己也能装的 <code>oh-my-openagent</code> 插件，不是内核新增的神秘能力——每一层都用原生钩子和工具白名单搭得出来。</p><h2 id="一、单循环-agent-的两个失败模式" tabindex="-1">一、单循环 Agent 的两个失败模式 <a class="header-anchor" href="#一、单循环-agent-的两个失败模式" aria-label="Permalink to &quot;一、单循环 Agent 的两个失败模式&quot;">​</a></h2><p>先把问题摆清。原生 runLoop 已经是一个&quot;感知 → 推理 → 行动 → 反馈&quot;的闭环，模型在这个循环里既能读文件、也能改文件、还能跑命令。那为什么还需要在它外面再叠一层 plan-execute 编排？因为单循环本身同时把两种失败模式放进了同一个上下文。</p><h3 id="_1-1-范围蔓延-边读边写、角色混乱、越改越偏" tabindex="-1">1.1 范围蔓延：边读边写、角色混乱、越改越偏 <a class="header-anchor" href="#_1-1-范围蔓延-边读边写、角色混乱、越改越偏" aria-label="Permalink to &quot;1.1 范围蔓延：边读边写、角色混乱、越改越偏&quot;">​</a></h3><p>想象你让一个单循环 agent 去&quot;重构 auth 模块，顺便加个限流&quot;。它通常的轨迹是：读二十来个相关文件 → 在上下文里逐步构建出对代码库的理解 → 直接开始 <code>Edit</code> 十几个文件 → 中途发现某个依赖要查，再回头看代码 → 改着改着，最初那条&quot;不要动数据库 schema&quot;的约束从上下文里被挤掉了。这不是模型笨，而是它把&quot;设计决策&quot;和&quot;逐文件修改&quot;塞进了同一个上下文，每读一个文件产出的新理解都在悄悄改写它自己对目标范围的心智模型。</p><p>范围蔓延的本质是<strong>决策与执行不分开</strong>。一个同时握有&quot;决定改哪里&quot;和&quot;实际动手改&quot;两种权力的 agent，会在执行过程中不断重新解释自己手里的范围——因为它每读一个文件，目标就可能被微调一次。这也让任务的可复现性变差：同样的需求，上一轮和下一轮可能收敛到完全不同的改动面。</p><h3 id="_1-2-验证缺口-模型说-完成了-但没人证明" tabindex="-1">1.2 验证缺口：模型说&quot;完成了&quot;，但没人证明 <a class="header-anchor" href="#_1-2-验证缺口-模型说-完成了-但没人证明" aria-label="Permalink to &quot;1.2 验证缺口：模型说&quot;完成了&quot;，但没人证明&quot;">​</a></h3><p>第二个失败模式更隐蔽。模型在最终答复里写下&quot;完成了&quot;，这句话在单循环里就是一个终结信号——控制流直接交还给用户，没有任何一方去核对&quot;完成&quot;是否成立。模型高估自己改动质量的倾向是 base rate 级别的，它给测试的乐观、它对某个边界的忽略，都不会被纠正，因为<strong>验证和执行共享同一个上下文、同一套先入为主</strong>。</p><p>这里先排除一个误读：验证缺口不等于没有测试。模型确实会&quot;跑测试&quot;，但&quot;跑了一遍测试且通过&quot;和&quot;独立于改动者的第三方去按验收标准证明它完成&quot;是两件事。前者是自证，后者才是关卡。</p><h3 id="_1-3-为什么单单一个-runloop-堵不住" tabindex="-1">1.3 为什么单单一个 runLoop 堵不住 <a class="header-anchor" href="#_1-3-为什么单单一个-runloop-堵不住" aria-label="Permalink to &quot;1.3 为什么单单一个 runLoop 堵不住&quot;">​</a></h3><p>runLoop（见本系列第二章）的设计目标是&quot;不间断地把一轮工具调用跑完&quot;，它没有区分规划态、执行态、验证态。它把三种不同的脑力负担——想清楚要做什么、照着做出来、证明做的对——揉进同一条循环，于是两个失败模式同时得手：范围蔓延来自&quot;决策权与执行权不分&quot;，验证缺口来自&quot;自证代替了关卡&quot;。</p><p>这一段推理逼出一个结论：要想同时堵住两种失败模式，系统需要把单一循环拆成<strong>有界的三阶段</strong>——只规划、只执行、只验证，每个阶段用一个独立的角色承担、用一道硬约束把它的操作范围钉死。这就是下面三节逐层展开的设计。</p><h2 id="二、拆成三态-plan-execute-verify-的角色分工" tabindex="-1">二、拆成三态：plan / execute / verify 的角色分工 <a class="header-anchor" href="#二、拆成三态-plan-execute-verify-的角色分工" aria-label="Permalink to &quot;二、拆成三态：plan / execute / verify 的角色分工&quot;">​</a></h2><p><img src="'+p+`" alt="三态分工与硬约束模型"></p><p>顺着上一段的推理，编排的第一步是把三阶段物化成三个独立角色，并给每个角色一份明确的&quot;什么能做、什么绝对不能碰&quot;的操作边界。oh-my-openagent 在 OpenCode 的 Agent 机制上（第五章已讲）用插件注册了整套角色名册。这里不谈全量名册，只留与论证主线直接相关的三个核心角色，机制比名单重要得多。</p><h3 id="_2-1-三态-三角色-只规划-只执行-只验证" tabindex="-1">2.1 三态 = 三角色：只规划 / 只执行 / 只验证 <a class="header-anchor" href="#_2-1-三态-三角色-只规划-只执行-只验证" aria-label="Permalink to &quot;2.1 三态 = 三角色：只规划 / 只执行 / 只验证&quot;">​</a></h3><p>三阶段各有专职角色：<strong>Plan</strong> 端是只读规划师 Prometheus；<strong>Execute</strong> 端分为指挥者（orchestrator）与执行者（worker）；<strong>Verify</strong> 端是验证关卡。三态各自隔离操作范围——规划师不写产品代码，执行者不自己决定范围，验证者不信任任何人的&quot;完成&quot;二字。</p><p>把这三者放一起看，背后是一条明确的分工原则：<strong>让握有范围定义权、实际改动权、结果评判权的三个实体互相独立</strong>。拆开之后，任何一个角色的上下文被污染，都不至于传染到另外两个——这直接对抗第一节的两个失败模式：范围定义权被隔离在规划态，改动权被隔离在执行态且受计划约束，评判权被隔离在验证态且不信任执行者的自述。</p><h3 id="_2-2-角色的操作边界-allowed-tools-白名单" tabindex="-1">2.2 角色的操作边界 = allowed-tools 白名单 <a class="header-anchor" href="#_2-2-角色的操作边界-allowed-tools-白名单" aria-label="Permalink to &quot;2.2 角色的操作边界 = allowed-tools 白名单&quot;">​</a></h3><p>角色划分不是靠提示词，而是靠 OpenCode 原生的工具白名单。插件在运行时解析每个 agent 的 <code>allowed-tools</code>（<code>parseAllowedTools</code>），把&quot;这个角色能用哪些工具&quot;固化成一份可执行的清单。白名单的好处是它是硬约束：不在名单里的工具，模型连调用入口都拿不到。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function parseAllowedTools(allowedTools) {</span></span>
<span class="line"><span>  // 把 agent 配置/文件的 &quot;allowed-tools&quot;: [...] 解析成工具白名单</span></span>
<span class="line"><span>  // 后续按 agent 名查表，决定把哪些工具暴露给该 session</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>工具白名单与三态分工互为表里：规划师的白名单天然不含产品代码写入工具，执行者白名单里没有&quot;改范围&quot;的入口。这张白名单是&quot;边界&quot;的运行载体——下面每一节讲的具体硬约束，都要落在它之上。</p><h3 id="_2-3-只保留与主线相关的核心角色" tabindex="-1">2.3 只保留与主线相关的核心角色 <a class="header-anchor" href="#_2-3-只保留与主线相关的核心角色" aria-label="Permalink to &quot;2.3 只保留与主线相关的核心角色&quot;">​</a></h3><p>插件注册了十几个 agent，但论证主线只需关注三个：规划师（plan）、指挥者 + 执行者（execute）、验证关卡（verify）。名册里其余的角色——如顾问、评审、检索、视觉审查等——服务于更精细的分工，但对&quot;范围蔓延 / 验证缺口&quot;这条主线不构成新的设计论点。下文只在这三个核心角色上展开——选择性地砍名册、留机制，因为这一章的要点是&quot;编排的骨架&quot;而不是&quot;插件有多少种开会方式&quot;。</p><h2 id="三、plan-只读规划是怎么被-硬强制-实施的" tabindex="-1">三、Plan：只读规划是怎么被&quot;硬强制&quot;实施的 <a class="header-anchor" href="#三、plan-只读规划是怎么被-硬强制-实施的" aria-label="Permalink to &quot;三、Plan：只读规划是怎么被&quot;硬强制&quot;实施的&quot;">​</a></h2><p>规划态是整套编排的起点，也是范围蔓延的防线。它的设计要点在于：<strong>规划权必须从执行权里剥出来</strong>，并且这个剥离不能只靠提示词，要用硬边界锁死。</p><h3 id="_3-1-为什么-规划权-要从-执行权-里剥出来" tabindex="-1">3.1 为什么&quot;规划权&quot;要从&quot;执行权&quot;里剥出来 <a class="header-anchor" href="#_3-1-为什么-规划权-要从-执行权-里剥出来" aria-label="Permalink to &quot;3.1 为什么&quot;规划权&quot;要从&quot;执行权&quot;里剥出来&quot;">​</a></h3><p>复用第一节的场景：一个既能规划又能执行的 agent，&quot;打算怎么做&quot;和&quot;实际怎么做&quot;在它脑子里没有分界。它可能一边写计划、一边就把计划里的改动顺手做了——而一旦开始做，范围就在执行中被悄悄改写。剥出来的好处是：<strong>规划只在只读的意义上接触项目</strong>，它产出一个可被审阅、可被存档的工件，而不是把理解直接折进修改动作里。规划师的任务是&quot;把要做什么钉死成一份文件&quot;，不是&quot;开始实现&quot;。</p><p>规划师的核心约束用一句话写在它的指令里：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REFUSE. Say: &quot;I&#39;m a planner. I create work plans, not implementations. Run \`/start-work\` after I finish planning.&quot;</span></span></code></pre></div><p>当用户让规划师&quot;直接实现&quot;时，它会明确拒绝并引向 <code>/start-work</code> 执行入口。这句话把&quot;规划师不实现&quot;从一句建议升成了一个不可规避的行为锚点。</p><h3 id="_3-2-两层强制-prompt-软约束-白名单硬边界" tabindex="-1">3.2 两层强制：prompt 软约束 + 白名单硬边界 <a class="header-anchor" href="#_3-2-两层强制-prompt-软约束-白名单硬边界" aria-label="Permalink to &quot;3.2 两层强制：prompt 软约束 + 白名单硬边界&quot;">​</a></h3><p>只靠 3.1 那行 REFUSE 是不够的——提示词是软约束，模型不听话就破功。所以在这之外还要有一层硬的：<strong>只读工具 + 写范围白名单</strong>。规划师的工具表明确写明：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| Tool | Allowed | Blocked |</span></span>
<span class="line"><span>|------|---------|---------|</span></span>
<span class="line"><span>| Write/Edit | \`.omo/**/*.md\` ONLY | Everything else |</span></span></code></pre></div><p>它在 <code>dist</code> 侧的常量化：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ALLOWED_EXTENSIONS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> BLOCKED_TOOLS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Edit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p><code>BLOCKED_TOOLS</code> 列出需要拦的写入工具，<code>ALLOWED_EXTENSIONS</code> 只放行 <code>.md</code>——规划师只能写 <code>.omo/</code> 下的 markdown 计划文件，除此之外一切写入都被拒。这套&quot;写范围白名单&quot;由 <code>prometheus-md-only</code> 钩子挂在 <code>tool.execute.before</code> 上强制执行，一旦规划师试图写 <code>.omo/*.md</code> 之外的任何路径，钩子就会 throw 拦截这次调用并抛一个明确原因的拒绝消息：<code>[prometheus-md-only] Prometheus is a planning agent. File operations restricted to .omo/*.md plan files only.</code> 这个&quot;只准写计划但禁止实现&quot;的状态在别处也被标注成 <code>plan-mode-only</code>（它对应的合法性拒绝文案），它和钩子 throw 是<strong>同一条规则在不同通道上的两个表述</strong>——前者拦的是规划师往队内通道发写操作，后者拦的是写文件，两者的判定依据都是&quot;plan-mode-only&quot;。连&quot;派一个子 agent 去代写&quot;也被堵死——<code>PLANNING_CONSULT_WARNING</code> 会被注入到规划师发起的顾问子 agent，明确告之&quot;你在被一个只读规划师调用，只提供分析，不要实现&quot;。</p><p>两层为什么都要：<strong>prompt 软约束给模型一个可理解的&quot;为什么不行&quot;，白名单硬约束保证模型&quot;破不了&quot;</strong>。前者管&quot;情愿&quot;，后者管&quot;能力&quot;——即使模型因为某种理由想越界，它也没法越过白名单。</p><h3 id="_3-3-计划的工件格式-checkbox-是可审计的进度载体" tabindex="-1">3.3 计划的工件格式：checkbox 是可审计的进度载体 <a class="header-anchor" href="#_3-3-计划的工件格式-checkbox-是可审计的进度载体" aria-label="Permalink to &quot;3.3 计划的工件格式：checkbox 是可审计的进度载体&quot;">​</a></h3><p>规划唯一的落盘产出是 <code>.omo/plans/*.md</code>。这份文件不仅是给人看的目标清单，更是整条编排的<strong>契约</strong>：执行端照着它打勾，验证端靠它判断进度。计划里每一项任务都是一个 checkbox（<code>- [ ] N. 任务</code>），执行时把它勾成 <code>- [x]</code>。计划文件与执行进度的绑定，让&quot;要做什么&quot;从模型的内存落到了磁盘上可审计的文件里——这正是范围蔓延的对立面：范围被钉在文件里，而不是飘在上下文里。</p><p>这样一份计划文件同时承担三个角色：给人审阅（用户能逐项改）、给机器校验（正则解析 checkbox）、给崩溃恢复（下节 boulder 基于它重建进度）。它是下一阶段 execute 的&quot;唯一事实源&quot;。</p><h2 id="四、execute-状态机怎么保证-可恢复-不偏离" tabindex="-1">四、Execute：状态机怎么保证&quot;可恢复 + 不偏离&quot; <a class="header-anchor" href="#四、execute-状态机怎么保证-可恢复-不偏离" aria-label="Permalink to &quot;四、Execute：状态机怎么保证&quot;可恢复 + 不偏离&quot;&quot;">​</a></h2><p><img src="`+d+'" alt="计划与状态机的双重闭环"></p><p>规划态产出计划文件后，执行态接手。执行态的设计要回答两个问题：怎么把 session 从&quot;规划&quot;切换成&quot;执行&quot;，以及怎么保证执行是&quot;照着计划来、且崩溃能续&quot;的。</p><h3 id="_4-1-start-work-钩子-阶段切换的一次性入口" tabindex="-1">4.1 /start-work 钩子：阶段切换的一次性入口 <a class="header-anchor" href="#_4-1-start-work-钩子-阶段切换的一次性入口" aria-label="Permalink to &quot;4.1 /start-work 钩子：阶段切换的一次性入口&quot;">​</a></h3><p>规划到执行的切换由命令 <code>/start-work</code> 触发。插件在 <code>chat.message</code> 钩子里识别这条命令，识别到之后做两件事：一是把当前 session 的 agent 从规划师切成执行端（<code>updateSessionAgent(input.sessionID, activeAgent)</code>，其中 <code>activeAgent = isAgentRegistered(&quot;atlas&quot;) ? &quot;atlas&quot; : &quot;sisyphus&quot;</code>），二是读取 boulder 状态决定是初始化还是续跑：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> activeAgent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> isAgentRegistered</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;atlas&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;atlas&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;sisyphus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">updateSessionAgent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input.sessionID, activeAgent);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 切到执行端</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> existingState</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> readBoulderState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx.directory);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 读编排状态</span></span></code></pre></div><p>这里用的是 OpenCode 原生的 session-agent 切换能力（<code>setSessionAgent</code> / <code>sessionAgentMap</code>）——插件没有改内核，只是在一个明确的命令入口上调用它。<code>/start-work</code> 因此是阶段切换的<strong>一次性闸门</strong>：规划态里绝不能绕过它直接开始实现；一旦经过此闸，当前 session 就正式进入执行态。</p><h3 id="_4-2-boulder-json-可查询、可恢复的编排状态机" tabindex="-1">4.2 boulder.json：可查询、可恢复的编排状态机 <a class="header-anchor" href="#_4-2-boulder-json-可查询、可恢复的编排状态机" aria-label="Permalink to &quot;4.2 boulder.json：可查询、可恢复的编排状态机&quot;">​</a></h3><p>执行态的状态中枢是一份磁盘 JSON：<code>.omo/boulder.json</code>。它记录当前 active work 的 <code>plan_name</code>、<code>status</code>、参与的 <code>session_ids</code>、任务-会话映射等。这样一个文件把&quot;现在做哪件事、做了几件、谁在做&quot;从某个 LLM 的上下文里抽出来，变成一个<strong>可查询、可恢复</strong>的事实。</p><p>状态落盘是&quot;崩溃可恢复&quot;的前提。LLM 会话很脆弱：进程崩、关机、token 超限被截断都很常见；如果进度只存在于上下文里，一旦中断就得重头来。把 <code>plan_name</code>/进度/会话映射持久化到 <code>boulder.json</code>，执行就能在重启后按状态续跑——这是&quot;可恢复&quot;这一设计点的工程落点。</p><h3 id="_4-3-执行端怎么-照着计划打勾" tabindex="-1">4.3 执行端怎么&quot;照着计划打勾&quot; <a class="header-anchor" href="#_4-3-执行端怎么-照着计划打勾" aria-label="Permalink to &quot;4.3 执行端怎么&quot;照着计划打勾&quot;&quot;">​</a></h3><p>boulder 解决&quot;可恢复&quot;，而&quot;不偏离&quot;靠执行端与计划文件的强绑定。执行者每完成一个任务，不是直接说&quot;我做完了&quot;，而是要<strong>回写计划文件里的 checkbox</strong>：把对应任务的 <code>- [ ]</code> 改成 <code>- [x]</code>，再 <code>Read</code> 一次计划文件确认未勾项确实减少了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. **EDIT the plan checkbox**: Change `- [ ]` to `- [x]` for the completed task in `.omo/plans/{plan-name}.md`</span></span>\n<span class="line"><span>2. **READ the plan to confirm**: Read `.omo/plans/{plan-name}.md` and verify the checkbox count changed (fewer `- [ ]` remaining)</span></span></code></pre></div><p>这招的用意是让执行者<strong>不自由发挥</strong>：进度的锚点始终是计划文件，而非执行者自己的叙述。执行者想推进&quot;完成&quot;，就必须先让计划里对应的项变成已勾——它被强制在写代码之外再做一次&quot;更新计划文件&quot;的动作，这个动作把它拉回计划这个唯一事实源，防止它在执行中悄悄扩大范围。</p><h3 id="_4-4-执行者的边界-只准按计划做-不准自己改范围" tabindex="-1">4.4 执行者的边界：只准按计划做，不准自己改范围 <a class="header-anchor" href="#_4-4-执行者的边界-只准按计划做-不准自己改范围" aria-label="Permalink to &quot;4.4 执行者的边界：只准按计划做，不准自己改范围&quot;">​</a></h3><p>执行角色被进一步约束：它要按计划里的 checkbox 挨个推进，不能被自己读到的代码带偏去改范围。这条边界与第二节的 allowed-tools 白名单一脉相承——执行者手里有&quot;改产品代码&quot;的工具，但没有&quot;改范围定义&quot;的入口；范围的任何变动都得回到规划态（重新起规划师、更新计划文件）才能生效，不能在执行态自我授权。</p><p>于是执行态的&quot;人不偏离&quot;由两条线保证：checkbox 回写把进度钉在计划文件上，boulder 的状态机保证中断后可续、范围可查。执行态把&quot;照着计划做&quot;从一句叮嘱变成了一个持久化的、可核对的过程。</p><h2 id="五、verify-验证关卡怎么挡住-模型说完成了" tabindex="-1">五、Verify：验证关卡怎么挡住&quot;模型说完成了&quot; <a class="header-anchor" href="#五、verify-验证关卡怎么挡住-模型说完成了" aria-label="Permalink to &quot;五、Verify：验证关卡怎么挡住&quot;模型说完成了&quot;&quot;">​</a></h2><p><img src="'+r+`" alt="对抗性验证的三重关卡"></p><p>执行阶段只能保证&quot;按计划推进&quot;，却无法确保&quot;结果完全正确&quot;。这正是验证机制（Verify Phase）发挥作用的场景。与多数系统采用的&quot;先信任后验证&quot;不同，OpenCode 的设计原则更为审慎——它默认子 Agent 的输出不可信，从而将&quot;结果验证&quot;从可选动作提升为不可绕过的硬性关卡。</p><h3 id="_5-1-buildcompletiongate-完成必须有证据-不是一句话" tabindex="-1">5.1 buildCompletionGate：完成必须有证据，不是一句话 <a class="header-anchor" href="#_5-1-buildcompletiongate-完成必须有证据-不是一句话" aria-label="Permalink to &quot;5.1 buildCompletionGate：完成必须有证据，不是一句话&quot;">​</a></h3><p>每完成一个任务，验证端会给执行者塞一段 <strong>COMPLETION GATE</strong>（<code>buildCompletionGate</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>**COMPLETION GATE - DO NOT PROCEED UNTIL THIS IS DONE**</span></span>
<span class="line"><span>Your completion will NOT be recorded until you complete ALL of the following:</span></span>
<span class="line"><span>1. **Edit** the plan file \`.omo/plans/{planName}.md\`: Change \`- [ ]\` to \`- [x]\`</span></span>
<span class="line"><span>2. **Read** the plan file AGAIN: verify the checkbox count changed</span></span>
<span class="line"><span>3. **DO NOT call \`task()\` again** until steps 1 and 2 are done.</span></span></code></pre></div><p>这一段的含义是：<strong>成功的唯一证据，是一个磁盘文件里的 checkbox 从&quot;未勾&quot;变成&quot;已勾&quot;</strong>。完成门并不接受&quot;我把代码改了&quot;这类叙述，它强制执行者在宣称完成之前，用一次写 + 一次读把可核对的进度变化落进计划文件。没走完这道门，执行者的&quot;完成&quot;不会被记录——它直接堵住了&quot;模型说做完了&quot;这种验证缺口的最浅形态。</p><h3 id="_5-2-verification-reminder-默认子-agent-在撒谎" tabindex="-1">5.2 VERIFICATION_REMINDER：默认子 agent 在撒谎 <a class="header-anchor" href="#_5-2-verification-reminder-默认子-agent-在撒谎" aria-label="Permalink to &quot;5.2 VERIFICATION_REMINDER：默认子 agent 在撒谎&quot;">​</a></h3><p>验证的灵魂在 <code>VERIFICATION_REMINDER</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>**THE SUBAGENT JUST CLAIMED THIS TASK IS DONE. THEY ARE PROBABLY LYING.**</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Subagents say &quot;done&quot; when code has errors, tests pass trivially, logic is wrong,</span></span>
<span class="line"><span>or they quietly added features nobody asked for. This happens EVERY TIME.</span></span>
<span class="line"><span>Assume the work is broken until YOU prove otherwise.</span></span></code></pre></div><p>它把&quot;子 agent 声称完成&quot;当成默认不可信的起点，并要求验证者用确定性工具去证明：<code>git diff --stat</code> 看改动范围、<code>Read</code> 每个被改文件、Grep 找 TODO/FIXME/@ts-ignore/空 catch、跑 <code>lsp_diagnostics</code> 检查每个改动文件没有新增错误、跑测试 / build 看退出码。整套&quot;证明机制&quot;都用可复现的工具产证据——而不是借另一个更强模型&quot;看一眼再判断&quot;。</p><h3 id="_5-3-验证的三重关卡-completion-gate-→-独立-review-→-final-wave" tabindex="-1">5.3 验证的三重关卡：Completion Gate → 独立 Review → Final Wave <a class="header-anchor" href="#_5-3-验证的三重关卡-completion-gate-→-独立-review-→-final-wave" aria-label="Permalink to &quot;5.3 验证的三重关卡：Completion Gate → 独立 Review → Final Wave&quot;">​</a></h3><p>&quot;不信任&quot;被固化成了三道递进的关卡：</p><ul><li><strong>关卡一：Completion Gate</strong>（5.1）——执行者要逐条自证（checkbox 全勾 + 测试跑过）才允许宣称完成。这一关拦的是&quot;口头完成&quot;。</li><li><strong>关卡二：独立 Review</strong>——在关卡一通过后，由执行者之外的独立 agent 按验收标准复跑关键路径，而非执行者自我评估。独立性的意义在于避开 1.2 说的&quot;自证代替关卡&quot;：评判者与执行者上下文不同，不共享执行时的先入为主。</li><li><strong>关卡三：Final Verification Wave</strong>——当所有实现 todo 都进入&quot;已勾&quot;，开始收尾的统验批次，它是<strong>把终审结论集中交给用户的唯一审批时刻</strong>：计划里的 <code>F1-F4</code> 是终审项，由 <code>shouldPauseForApproval</code> 决定是走 final-wave 审批还是普通完成门：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Final Wave 任务是 APPROVAL GATES——不是普通任务。</span></span>
<span class="line"><span>在所有实现任务完成前，不进入 Final Wave。</span></span></code></pre></div><p>于是整套流程里，规划、执行、自动验证不在中途向用户要<strong>审批式</strong>的确认，只有结尾这一次把终审结论交给用户做最终裁决；就算流程中发现有&quot;待用户决策&quot;的分支，也只在需要人工拍板时暂停一次。前面三道关卡把&quot;验证缺口&quot;一层层堵住，用户审批点则把&quot;机器不敢独自拍板&quot;的最后一道门守住。</p><h3 id="_5-4-对抗性设计哲学-为什么默认不信" tabindex="-1">5.4 对抗性设计哲学：为什么默认不信 <a class="header-anchor" href="#_5-4-对抗性设计哲学-为什么默认不信" aria-label="Permalink to &quot;5.4 对抗性设计哲学：为什么默认不信&quot;">​</a></h3><p>把 5.1-5.3 放在一起会看到一个共同点：验证不给&quot;信任&quot;留位置。设计者的假设是<strong>幻觉和过度乐观是 base rate</strong>——子 agent 说&quot;完成&quot;时，大概率有某处错了，只是它没看到。所以验证的起点是&quot;默认坏、去证明它好&quot;，而不是&quot;默认好、去抽查它坏&quot;。</p><p>这与&quot;信任但验证&quot;的区别很实在：信任模式把举证责任放给执行者（证明自己做对了），对抗模式把举证责任放给验证者（先假设坏，再证明好）。放给验证者更稳，因为验证者手里握的是 <code>git diff</code>/<code>lsp</code>/测试这类<strong>处置过程可复现的证据链</strong>，而不是执行者那套先入为主的叙述。这套&quot;默认不信&quot;的信念，正是 verify 态之所以能堵住验证缺口的根源。</p><h2 id="六、这套编排给原生内核的启示" tabindex="-1">六、这套编排给原生内核的启示 <a class="header-anchor" href="#六、这套编排给原生内核的启示" aria-label="Permalink to &quot;六、这套编排给原生内核的启示&quot;">​</a></h2><p>把三阶段走完，回到一个更本质的问题：这套编排到底是插件发明的，还是 OpenCode 原生就能拼出来的？答案更接近后者——原生已经把&quot;积木&quot;备齐，插件做的是把积木按纪律搭起来。</p><h3 id="_6-1-原生给齐了积木-插件只是搭法" tabindex="-1">6.1 原生给齐了积木，插件只是搭法 <a class="header-anchor" href="#_6-1-原生给齐了积木-插件只是搭法" aria-label="Permalink to &quot;6.1 原生给齐了积木，插件只是搭法&quot;">​</a></h3><p>OpenCode 原生提供了三样拼装这套编排所需的底层：<strong>工具白名单 + allowed-tools</strong>（决定角色能调什么工具）、<strong>Agent/SubAgent 机制</strong>（第五章已讲，<code>task</code> 委派 + 权限派生）、以及 <strong>tool.execute.before/after 等钩子</strong>（把&quot;硬边界&quot;挂在调用生命周期的关卡上）。<code>prometheus-md-only</code> 这类钩子写死非 <code>.omo</code> 写入，本质是挂在一个原生钩子上做策略判断，没有篡改内核任何一行。</p><p>这让&quot;插件可扩展&quot;成为可证结论：机制是原生给的，策略是插件定的。任何想在原生 OpenCode 上做 plan-execute-verify 的人，都能用同一套积木搭出自己的版本——只读规划 agent、写入守门钩子、一个 <code>.json</code> 状态载体。</p><h3 id="_6-2-三层硬约束的通用性-只读边界-状态机-验证关卡" tabindex="-1">6.2 三层硬约束的通用性：只读边界 / 状态机 / 验证关卡 <a class="header-anchor" href="#_6-2-三层硬约束的通用性-只读边界-状态机-验证关卡" aria-label="Permalink to &quot;6.2 三层硬约束的通用性：只读边界 / 状态机 / 验证关卡&quot;">​</a></h3><p>这套编排值得记住的不是某个角色名，而是三条可以迁移到任何 Agent 系统的<strong>通用硬约束</strong>：</p><table tabindex="0"><thead><tr><th>阶段</th><th>硬约束</th><th>堵住哪个失败模式</th></tr></thead><tbody><tr><td>Plan</td><td>只读硬边界（allowed-tools + hook reject）</td><td>范围蔓延（决策权不越界）</td></tr><tr><td>Execute</td><td>状态机（boulder + checkbox 回写）</td><td>范围蔓延（不偏离计划）+ 可恢复</td></tr><tr><td>Verify</td><td>验证关卡（Gate + 独立 Review + Final Wave）</td><td>验证缺口（证明替代自述）</td></tr></tbody></table><p>这三条约束是正交的：只读边界管&quot;不能越界&quot;、状态机管&quot;不偏离且能续&quot;、验证关卡管&quot;完成可证明&quot;。任何一个失败模式都至少被其中一层承接。这正是第一节那段推理的最短落实——单一循环堵不住的两个问题，被三态各自的硬约束分段堵住。</p><h3 id="_6-3-回扣主线-总对比" tabindex="-1">6.3 回扣主线 + 总对比 <a class="header-anchor" href="#_6-3-回扣主线-总对比" aria-label="Permalink to &quot;6.3 回扣主线 + 总对比&quot;">​</a></h3><p>把论证链收口：<strong>范围蔓延</strong>由 Plan 的只读硬边界与 Execute 的 checkbox 回写双重兜底（决策权在规划态被隔离，改动范围在执行态被钉死）；<strong>验证缺口</strong>由 Verify 的对抗性关卡堵住（完成必须有证据、且最终要过用户审批）。三层硬约束，两个失败模式，设计闭环。</p><table tabindex="0"><thead><tr><th>维度</th><th>OpenCode 原生</th><th>oh-my-openagent</th></tr></thead><tbody><tr><td>只读规划</td><td><code>plan</code> agent + edit <code>*: deny</code></td><td>可另起只读 agent + hook 硬 reject 非 <code>.omo</code> 写入</td></tr><tr><td>阶段切换</td><td><code>/plan</code>、agent 切换原语</td><td><code>/start-work</code> → <code>updateSessionAgent</code> 一次性闸门</td></tr><tr><td>执行状态</td><td>Session/Snapshot 持久化</td><td>boulder.json 状态机（可恢复、可查询）</td></tr><tr><td>验证</td><td>lsp/bash 等确定性工具</td><td>Completion Gate + 独立 Review + Final Wave 三道关卡</td></tr><tr><td>保障机制</td><td>提供工具与钩子，不决定策略</td><td>在原生钩子上把&quot;严格角色分离 + 可证明完成&quot;编排成纪律</td></tr></tbody></table><p>一句话回扣主线：<strong>这套编排的价值在于用最少的抽象层把&quot;想、做、验&quot;三个本来挤在单循环里的负担拆开，并用只读边界、状态机、验证关卡三道硬约束各自堵住一个失败模式</strong>。它对原生内核的启示是：能抗住范围蔓延与验证缺口的，不是更强的模型，而是&quot;决策权、改动权、评判权互相隔离 + 每权都有一道它破不了的硬边界&quot;的编排纪律——所有积木，原生都已给齐。</p><h2 id="章节小测" tabindex="-1">章节小测 <a class="header-anchor" href="#章节小测" aria-label="Permalink to &quot;章节小测&quot;">​</a></h2>`,96)),l(o,{questions:e})])}}});export{g as __pageData,k as default};
